import json
import re
import pandas as pd
from .mappings import VARIABLES,CODEBOOK,CALCULATED,LEAKAGE

def table(df):
    # Avoid an extra optional tabulate dependency.
    return '| '+' | '.join(map(str,df.columns))+' |\n| '+' | '.join(['---']*len(df.columns))+' |\n'+ '\n'.join('| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in df.itertuples(index=False,name=None))+'\n'

def reports(root,raw,clean,missing,summary,validation,splits,hashes):
    out=root/'reports'; processed=root/'data/processed'
    sources=f'\n\nSources: [CDC 2021 codebook]({CODEBOOK}); [CDC calculated variables]({CALCULATED}); [CDC dependency matrix](https://www.cdc.gov/brfss/annual_data/2021/summary_matrix_21.html). Local PDFs and extracted text are in docs/.\n'
    dictionary=[]; selection=[]; mobile=[]
    for original,s in VARIABLES.items():
        m=missing.set_index('variable').loc[original]
        rule='Unrecognized codes fail the build. Blank stays missing; documented nonresponses map to missing. No imputation.'
        mapping=json.dumps(s['mapping'],sort_keys=True) if original!='_BMI5' else 'Divide integer _BMI5 by 100; outside documented 12.00-99.99 range becomes missing.'
        dictionary.append(dict(original_variable=original,clean_variable=s['name'],description=s['question'],original_codes=json.dumps(list(s['labels'])),original_labels=json.dumps(s['labels']),clean_mapping=mapping,missing_value_rule=rule,data_type='nullable float' if original=='_BMI5' else 'nullable integer',feature_type='numeric' if s['kind']=='continuous' else 'categorical',ordinal_or_nominal=s['kind'],used_in_model=True,used_in_mobile_app=True,reason_for_inclusion_or_exclusion=s['reason'],source_document=CODEBOOK+'; '+CALCULATED))
        selection.append(dict(variable=original,available=True,missing_percent=round(float(m.missing_percentage),3),decision='Retain provisionally',mobile=s['usability'],reason=s['reason']))
        mobile.append(f'## {s["name"]} ({original})\n\nClassification: {s["usability"]}.\n\nQuestion: {s["question"]}\n\nCDC options: {json.dumps(s["labels"],ensure_ascii=False)}\n\nInternal mapping: {mapping}\n\nValidation: '+('BMI = kg / metres squared; 12.00 through 99.99 accepted. Values outside this range must be reviewed, never clamped.' if original=='_BMI5' else 'Only listed options allowed; unknown/refused/skipped answers become missing. The questionnaire must preserve wording and category boundaries.')+'\n\n'+('Medical/lab knowledge: prior professional diagnosis needed; no new laboratory numeric result is requested.' if s['usability']=='requires known medical history' else 'Medical/lab knowledge: no diagnosis or laboratory result required; BMI requires measurement.')+'\n')
    dictionary.append(dict(original_variable='_MICHD',clean_variable='heart_disease',description='Ever reported CHD or MI, not future event risk',original_codes='1,2,blank',original_labels='1: reported MI/CHD; 2: neither reported; blank: unavailable',clean_mapping='1 -> 1; 2 -> 0; blank -> exclude row',missing_value_rule='Exclude missing target; unexpected codes fail',data_type='integer',feature_type='target',ordinal_or_nominal='binary',used_in_model='target only',used_in_mobile_app=False,reason_for_inclusion_or_exclusion='Supervised label, never input',source_document=CODEBOOK+'; '+CALCULATED))
    for original in ['CVDINFR4','CVDCRHD4']:
        dictionary.append(dict(original_variable=original,clean_variable='',description='Direct target source: reported MI' if original=='CVDINFR4' else 'Direct target source: angina/CHD',original_codes='1,2,7,9,blank',original_labels='1 Yes; 2 No; 7 unknown; 9 refused; blank not asked/missing',clean_mapping='Excluded',missing_value_rule='Not applicable',data_type='raw numeric',feature_type='excluded',ordinal_or_nominal='nominal',used_in_model=False,used_in_mobile_app=False,reason_for_inclusion_or_exclusion='Direct target leakage',source_document=CODEBOOK+'; '+CALCULATED))
    # Share the documentation-only generator so future builds preserve the 17-row
    # dictionary schema and the mobile questionnaire fields.
    from .build_data_dictionary import write_dictionary
    write_dictionary(root)
    (out/'feature_selection_report.md').write_text('# Feature selection before exclusions\n\nAll 16 requested candidates are present and documented. Retained deterministically for a baseline prevalence-classification dataset; no target-association selection was performed. No candidate is permanently excluded. Missingness alone does not justify complete-case deletion. All other raw columns are outside this approved scope, not demonstrated irrelevant.\n\n'+table(pd.DataFrame(selection))+'\nGeneral health, walking difficulty and stroke history have unresolved temporal relationships. Income has nonresponse, sensitivity and fairness concerns. High cholesterol is conditional on screening and must not treat lack of testing as No. Education and income may encode structural inequities; later compare training-only feature alternatives. SEXVAR is the survey respondent-sex field, not gender identity; applicability outside those categories requires design review.\n'+sources,encoding='utf-8')
    missing.to_csv(out/'missingness_counts.csv',index=False)
    (out/'missingness_analysis.md').write_text('# Candidate missingness before row removal\n\n'+table(missing)+'\nNot-asked counts cannot be separated from ordinary missing using BLANK alone. The table therefore reports not_asked_or_missing, not a guessed count. Some calculated categories combine unknown/refused/missing; separate counts are not identifiable from that variable and are represented in the combined column. Other-invalid counts exclude documented nonresponses.\n\nPolicy: remove missing target only; retain all missing predictors as nullable values. No complete-case deletion, imputation, scaling, frequency encoding, or resampling. Later fit imputation and any missing indicators on training only, or use a model with native missing-value support. Missingness is not necessarily random (particularly cholesterol testing, BMI, income).\n'+sources,encoding='utf-8')
    # Audit all variable entries, including wording and category labels.
    text=(root/'docs/codebook21.txt').read_text(encoding='utf-8')
    parts=re.split(r'SAS Variable Name:\s*',text)[1:]
    audited=[]
    for part in parts:
        name=part.split()[0]
        part=part.split('\nLabel:',1)[0]
        hits=[term for term in ['coronary','myocardial','heart attack','angina','heart disease','cardiovascular'] if term in part.lower()]
        if hits: audited.append(dict(variable=name,matched_terms=', '.join(hits),present_in_xpt=name in raw))
    pd.DataFrame(audited).to_csv(out/'leakage_keyword_audit.csv',index=False)
    doc_variables={part.split()[0] for part in parts}
    pd.DataFrame([dict(variable=v,documented=v in doc_variables,decision='Exclude direct target leakage' if v in LEAKAGE else 'Approved candidate' if v in VARIABLES else 'Outside approved feature scope') for v in raw]).to_csv(out/'all_variable_leakage_audit.csv',index=False)
    (out/'leakage_analysis.md').write_text('# Target leakage audit\n\n| Variable | Reason for exclusion | Relationship with target |\n| --- | --- | --- |\n| _MICHD | Label cannot be a predictor | Exact target |\n| CVDINFR4 | Explicit prior heart attack/MI diagnosis | Direct CDC source |\n| CVDCRHD4 | Explicit angina/CHD diagnosis | Direct CDC source |\n\nCDC logic: either source equals 1 -> _MICHD=1; both equal 2 -> _MICHD=2; otherwise missing. A Yes takes precedence over an unknown in the other source. The pipeline verifies this derivation against every raw row.\n\nAll available codebook variable definitions were searched for coronary, myocardial, heart attack, angina, heart disease and cardiovascular. Matched variables are in leakage_keyword_audit.csv; every requested predictor was separately reviewed. CRGVPRB3 mentions heart disease for the person cared for, not the respondent; it is outside the selected feature scope and is not a direct source of the respondent target. No other documented explicit respondent CHD/MI diagnosis was found. Documentation gap: raw USEMRJN3 has no entry in the downloaded codebook. It is outside the candidate scope, remains excluded, and has not been interpreted. An official 2021 USEMRJN3 definition would be required before considering it. All selected variables have confirmed definitions. Therefore this audit cannot claim interpretation of every unselected raw field. The dependency matrix lists only the two direct sources for _MICHD.\n\nGeneral health, disability, stroke and lifestyle could follow a diagnosis. They are potential temporal proxies, not documented encodings of the target. This cross-sectional dataset cannot establish when they occurred. It is prepared for classification of reported prevalent CHD/MI; a claim of prospective risk would require a different outcome and temporal data. Statistical correlation is not proof of leakage. Identifiers, sampling weights, geography, and every unapproved raw field are absent from predictors.\n\nIdentical complete cleaned records are assigned to one split; source-row IDs also have disjoint membership. Different people can share identical predictors with different labels; that does not duplicate the same labeled record.\n'+sources,encoding='utf-8')
    (out/'mobile_feature_mapping.md').write_text('# Mobile questionnaire mapping\n\nNo UI is built. All unknown or skipped responses remain missing; the later inference pipeline must match training handling. These questions classify a survey label and do not establish future cardiovascular-event probability.\n\n'+'\n'.join(mobile)+sources,encoding='utf-8')
    bmi=raw['_BMI5']/100
    stats=bmi.describe(percentiles=[.01,.05,.25,.5,.75,.95,.99]).to_frame('bmi').reset_index(names='statistic')
    stats.to_csv(out/'bmi_summary.csv',index=False)
    invalid=raw['_BMI5'].notna() & (~raw['_BMI5'].between(1200,9999)|raw['_BMI5'].ne(raw['_BMI5'].round()))
    raw.loc[invalid,['_BMI5']].to_csv(out/'invalid_bmi_records.csv',index_label='source_row_id')
    # Descriptive review flag only, not a medical validity cutoff or exclusion.
    extreme=bmi.lt(15)|bmi.gt(60)
    raw.loc[extreme,['_BMI5']].assign(bmi=bmi[extreme]).to_csv(out/'bmi_review_records.csv',index_label='source_row_id')
    balance=[]
    for name,df in {'full_cleaned':clean,**splits}.items():
        for label in [0,1]:
            count=int(df.heart_disease.eq(label).sum())
            balance.append(dict(dataset=name,target=label,count=count,percentage=round(count/len(df)*100,6),dataset_rows=len(df)))
    balance=pd.DataFrame(balance); balance.to_csv(out/'class_balance.csv',index=False)
    (out/'class_balance.md').write_text('# Class imbalance after splitting\n\n'+table(balance)+'\nNo balancing/resampling performed. Majority-to-minority ratios are descriptive; these are unweighted survey counts, not population prevalence estimates. Test labels were used only for requested split-integrity and class-count validation; no model selection or preprocessing has used the test set.\n',encoding='utf-8')
    removed=len(raw)-len(clean)
    final=dict(original_rows=len(raw),original_columns=len(raw.columns),cleaned_rows=len(clean),cleaned_columns=len(clean.columns),rows_removed=removed,percentage_retained=len(clean)/len(raw)*100,final_predictor_count=len(VARIABLES),positive_count=int(clean.heart_disease.sum()),negative_count=int(clean.heart_disease.eq(0).sum()),positive_percentage=float(clean.heart_disease.mean()*100))
    final['original_feature_count']=len(raw.columns)-1
    final['candidate_feature_count']=len(VARIABLES)
    final['split_rows']={k:len(v) for k,v in splits.items()}
    (out/'cleaning_summary.json').write_text(json.dumps(final,indent=2))
    (out/'validation_report.json').write_text(json.dumps(validation,indent=2))
    (out/'cleaning_report.md').write_text('# Cleaning report\n\n'+table(pd.DataFrame([final]).drop(columns='split_rows').T.reset_index().rename(columns={'index':'metric',0:'value'}))+'\nTarget: reported existing CHD or MI from _MICHD; 1 -> 1, 2 -> 0. This is not a future-risk label.\n\nCandidates: '+', '.join(VARIABLES)+'\n\nFinal predictors: '+', '.join(clean.columns[:-1])+'.\n\nExclusions: every raw column outside the selected 16 predictors and target. Direct leakage exclusions: _MICHD as input, CVDINFR4, CVDCRHD4. No requested candidate permanently removed; all are provisional.\n\nCDC mappings and code-level nonresponse rules are recorded in data_dictionary.csv and src/data/mappings.py. Diabetes retains four meaningful categories. Smoking retains the 100-cigarette lifetime threshold; category 4 is not literally zero lifetime cigarettes. Hypertension No includes pregnancy-only/borderline. No global 7/9/77/99 recoding.\n\nRow removal ledger: raw '+str(len(raw))+'; missing/unusable target removed '+str(removed)+'; predictor-missing rows removed 0; duplicates removed 0; final '+str(len(clean))+'. Equal projected records retained as distinct people; no source row was duplicated.\n\nBMI: CDC codebook confirms two implied decimal places; calculated-variable SAS code explicitly multiplies BMI by 100 for release. Divide by 100. CDC construction bounds are 12.00 to 99.99; undocumented integer/range values become missing and are separately listed. Invalid count: '+str(int(invalid.sum()))+'.\n\n'+table(stats)+'\nDescriptive review flags below 15 or above 60: '+str(int(extreme.sum()))+'; retained, not claimed to be impossible. Flags are an audit heuristic, not a clinical cutoff. Valid extremes are never automatically removed.\n\nMissing predictors retained; imputation/encoding/scaling/balancing and learned feature selection must be fit on training only.\n\nSplit: seed 42; randomized identical-record groups allocated within each target class to 70/15/15 row quotas. Largest groups assigned first; ties shuffled. Small group-size rounding differences are possible. Pairwise source-row and exact labeled-record intersections verified empty; union and row counts reconcile. Membership is in split_membership.csv, never a predictor.\n\n'+table(balance)+'\nValidation: '+json.dumps(validation)+'.\n\nReproducibility: raw/ZIP SHA-256 recorded and checked before/after build; output SHA-256 manifest generated. Two builds must match deterministically.\n\nUnresolved concerns: USEMRJN3 is unselected and lacks a definition in the downloaded codebook (see all_variable_leakage_audit.csv); cross-sectional timing, self-reported diagnoses, sampling/design weights, reporting-area coverage, representation, income fairness/nonresponse and cholesterol-screening missingness. This dataset is ready for a reproducible baseline training pipeline that handles missing values, not for clinically validated future-risk deployment. No model has been trained.\n'+sources,encoding='utf-8')
    return final
